from pathlib import Path
import importlib.util

folder=Path(__file__).parent
spec=importlib.util.spec_from_file_location('direction_report',folder/'build_report.py')
report=importlib.util.module_from_spec(spec)
spec.loader.exec_module(report)

def local_image(name,alt):
    import base64
    data=base64.b64encode((folder/name).read_bytes()).decode()
    return f'<figure><img src="data:image/png;base64,{data}" alt="{alt}"><figcaption>{alt}</figcaption></figure>'

